            ind = len(body) - len(body.lstrip())
            if body.strip() and (ind <= step_indent or re.match(r"^\s{%d}-\s+" % step_indent, lines[step_end])):
                break
            step_end += 1
        run_i = next((i for i in range(step_i, step_end)
                      if re.match(r"^\s*(?:-\s*)?run\s*:", lines[i])), None)
        if run_i is None:
            continue
        run_line = lines[run_i]
        rm = re.match(r"^(\s*)(?:-\s*)?run\s*:\s*(.*?)(?:\r?\n)?$", run_line)
        run_indent = len(rm.group(1))
        code_end = run_i + 1
        if rm.group(2).strip() in ("|", ">", "|-", ">-") or not rm.group(2).strip():
